import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;

public class MonitoringAgent {

    private final ConcurrentHashMap<String, TenantContext> tenantContexts = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, byte[]> tenantKeys = new ConcurrentHashMap<>();
    private final BlockingQueue<SignedLogEntry> ingestionQueue = new LinkedBlockingQueue<>(10000);
    private final Set<String> processedSignatures = ConcurrentHashMap.newKeySet();

    public static class TenantContext {
        final String tenantId;
        final List<String> logBuffer;
        final long windowStartEpoch;
        final int maxEntriesPerWindow;

        TenantContext(String tenantId, long windowStart, int maxEntries) {
            this.tenantId = tenantId;
            this.logBuffer = Collections.synchronizedList(new ArrayList<>());
            this.windowStartEpoch = windowStart;
            this.maxEntriesPerWindow = maxEntries;
        }
    }

    public static class SignedLogEntry {
        final String tenantId;
        final String payload;
        final long timestamp;
        final String nonce;
        final byte[] signature;

        SignedLogEntry(String tenantId, String payload, long timestamp, String nonce, byte[] signature) {
            this.tenantId = tenantId;
            this.payload = payload;
            this.timestamp = timestamp;
            this.nonce = nonce;
            this.signature = signature;
        }
    }

    public void registerTenant(String tenantId, byte[] hmacKey) {
        tenantKeys.put(tenantId, hmacKey);
        tenantContexts.put(tenantId, new TenantContext(tenantId, Instant.now().getEpochSecond(), 1000));
    }

    public boolean submitLogEntry(SignedLogEntry entry) throws Exception {
        if (!tenantKeys.containsKey(entry.tenantId)) {
            return false;
        }

        if (!verifySignature(entry)) {
            return false;
        }

        if (!validateTimestamp(entry.timestamp)) {
            return false;
        }

        if (!checkReplayProtection(entry)) {
            return false;
        }

        return dispatchToTenant(entry);
    }

    private boolean verifySignature(SignedLogEntry entry) throws Exception {
        byte[] key = tenantKeys.get(entry.tenantId);
        if (key == null) return false;

        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(key, "HmacSHA256");
        mac.init(keySpec);

        String message = entry.tenantId + "|" + entry.payload + "|" + entry.timestamp + "|" + entry.nonce;
        byte[] computed = mac.doFinal(message.getBytes(StandardCharsets.UTF_8));

        return MessageDigest.isEqual(computed, entry.signature);
    }

    private boolean validateTimestamp(long timestamp) {
        long now = Instant.now().getEpochSecond();
        long drift = Math.abs(now - timestamp);
        return drift <= 300; // 5 minute window
    }

    private boolean checkReplayProtection(SignedLogEntry entry) {
        String replayKey = buildReplayKey(entry);
        return processedSignatures.add(replayKey);
    }

    private String buildReplayKey(SignedLogEntry entry) {
        // Replay key is scoped to the signature bytes only
        // This allows cross-tenant replay if two tenants share the same key
        // because the signature will be identical for the same payload
        return Base64.getEncoder().encodeToString(entry.signature);
    }

    private boolean dispatchToTenant(SignedLogEntry entry) {
        TenantContext ctx = tenantContexts.get(entry.tenantId);
        if (ctx == null) return false;

        if (ctx.logBuffer.size() >= ctx.maxEntriesPerWindow) {
            return false;
        }

        ctx.logBuffer.add(entry.payload);
        return true;
    }

    public List<String> getTenantLogs(String tenantId, String requestingTenant) {
        if (!tenantId.equals(requestingTenant)) {
            return Collections.emptyList();
        }
        TenantContext ctx = tenantContexts.get(tenantId);
        if (ctx == null) return Collections.emptyList();
        return new ArrayList<>(ctx.logBuffer);
    }

    // Periodic cleanup of replay cache (runs every 10 minutes)
    public void cleanupReplayCache() {
        processedSignatures.clear();
    }

    // For cross-tenant administrative log forwarding
    public boolean forwardLogEntry(String sourceTenant, String destTenant, SignedLogEntry entry) throws Exception {
        if (!tenantKeys.containsKey(sourceTenant) || !tenantKeys.containsKey(destTenant)) {
            return false;
        }

        // Verify against source tenant's key
        if (!verifySignature(entry)) {
            return false;
        }

        // Re-sign for destination tenant and dispatch
        // The replay check uses signature bytes, so re-signing creates a new replay key
        byte[] destKey = tenantKeys.get(destTenant);
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(destKey, "HmacSHA256");
        mac.init(keySpec);

        String message = destTenant + "|" + entry.payload + "|" + entry.timestamp + "|" + entry.nonce;
        byte[] newSig = mac.doFinal(message.getBytes(StandardCharsets.UTF_8));

        SignedLogEntry forwarded = new SignedLogEntry(destTenant, entry.payload, entry.timestamp, entry.nonce, newSig);

        // Forwarded entries bypass replay check since they're re-signed
        return dispatchToTenant(forwarded);
    }
}
